template <class Mutex>

void swap(unique_lock<Mutex> &lhs,

    unique_lock<Mutex> &rhs) noexcept;

recommendedExamples.code:
#include <iostream>
#include <mutex>

int main() {
    std::mutex mtx1;
    std::unique_lock<std::mutex> guard1(mtx1);
    std::unique_lock<std::mutex> guard2;
    guard2.swap(guard1);

    if (!guard1 && guard2)
        std::cout << "swapped success\n";

    return 0;
}
